	$request=static function(string$path,string$cookie='',?array$form=null)use($port):array{$curl=curl_init('http://127.0.0.1:'.$port.$path);$headers=array('Host: adc-verification.invalid');if($cookie){$headers[]='Cookie: '.$cookie;}$options=array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>15,CURLOPT_FOLLOWLOCATION=>false);if(null!==$form){$options[CURLOPT_POST]=true;$options[CURLOPT_POSTFIELDS]=http_build_query($form);}curl_setopt_array($curl,$options);$response=curl_exec($curl);if(false===$response){throw new RuntimeException('HTTP request failed');}$status=(int)curl_getinfo($curl,CURLINFO_RESPONSE_CODE);$size=(int)curl_getinfo($curl,CURLINFO_HEADER_SIZE);curl_close($curl);return array($status,substr($response,$size),substr($response,0,$size));};
